"""Riksdag roll-call map: near-unanimous filter, party PCA, member projection without centre-pull."""

import unittest

import numpy as np

from scripts.riksdag_votes.constants import MIN_MP_MAP_VOTES
from scripts.riksdag_votes.ideal_points import fit_party_map, is_near_unanimous, project_member

PARTIES = ("M", "L", "C", "KD", "S", "V", "MP", "SD")


def rank_two_party_matrix(votes: int = 120, seed: int = 7) -> np.ndarray:
    """Party codes in {-1, 0, 1} generated by two latent dimensions (cut-line model)."""
    rng = np.random.default_rng(seed)
    positions = np.array(
        [[0.6, 0.1], [0.5, 0.2], [0.1, -0.6], [0.6, 0.0], [-0.4, -0.5], [-0.8, 0.5], [-0.7, 0.3], [0.7, -0.1]]
    )
    matrix = np.zeros((len(PARTIES), votes))
    for i in range(votes):
        normal = rng.normal(size=2)
        normal /= np.linalg.norm(normal)
        cut = rng.uniform(-0.4, 0.4)
        side = positions @ normal - cut
        matrix[:, i] = np.where(side > 0.05, 1.0, np.where(side < -0.05, -1.0, 0.0))
    return matrix


class NearUnanimousTests(unittest.TestCase):
    def test_threshold_is_two_and_a_half_percent_of_ja_plus_nej(self) -> None:
        self.assertFalse(is_near_unanimous(39, 1))  # 1/40 = 2.5 % is kept
        self.assertTrue(is_near_unanimous(40, 1))  # 1/41 < 2.5 %
        self.assertTrue(is_near_unanimous(1, 300))
        self.assertTrue(is_near_unanimous(0, 0))
        self.assertFalse(is_near_unanimous(175, 174))


class PartyMapTests(unittest.TestCase):
    def setUp(self) -> None:
        self.matrix = rank_two_party_matrix()
        self.fitted = fit_party_map(self.matrix, PARTIES)

    def test_explained_variance_sums_to_one(self) -> None:
        ratio = self.fitted.explained_variance_ratio
        self.assertAlmostEqual(float(ratio.sum()), 1.0, places=12)
        self.assertTrue(np.all(np.diff(ratio) <= 1e-12))

    def test_orientation_anchor_positive(self) -> None:
        self.assertGreater(self.fitted.party_scores[PARTIES.index("M"), 0], 0)
        self.assertGreater(self.fitted.party_scores[PARTIES.index("SD"), 1], 0)
        flipped = fit_party_map(-self.matrix, PARTIES)
        self.assertGreater(flipped.party_scores[PARTIES.index("M"), 0], 0)

    def test_missing_values_rejected(self) -> None:
        matrix = self.matrix.copy()
        matrix[0, 0] = np.nan
        with self.assertRaises(ValueError):
            fit_party_map(matrix, PARTIES)

    def test_party_line_member_projects_onto_party_point(self) -> None:
        """Consistency: a member who always votes the party line lands on the party."""
        for index, party in enumerate(PARTIES):
            with self.subTest(party=party):
                point, n_cast, reason = project_member(self.matrix[index], self.fitted.mu, self.fitted.loadings)
                self.assertIsNone(reason)
                self.assertEqual(n_cast, self.matrix.shape[1])
                np.testing.assert_allclose(point, self.fitted.party_scores[index], atol=1e-9)

    def test_no_centre_pull_for_frequent_absentee(self) -> None:
        """Absent on half the votes: still (near) the party point, unlike zero-imputation."""
        rng = np.random.default_rng(3)
        for index, party in enumerate(PARTIES):
            codes = self.matrix[index].copy()
            absent = rng.choice(codes.size, size=codes.size // 2, replace=False)
            codes[absent] = np.nan
            point, n_cast, _ = project_member(codes, self.fitted.mu, self.fitted.loadings)
            party_point = self.fitted.party_scores[index]
            scale = np.linalg.norm(party_point) + 1e-9
            with self.subTest(party=party):
                self.assertEqual(n_cast, codes.size - codes.size // 2)
                self.assertLess(np.linalg.norm(point - party_point) / scale, 0.25)
                imputed = np.where(np.isnan(codes), 0.0, codes)
                pulled = self.fitted.loadings.T @ (imputed - self.fitted.mu)
                # Zero-imputation would have moved the member towards the centre.
                self.assertLess(np.linalg.norm(point - party_point), np.linalg.norm(pulled - party_point) + 1e-9)

    def test_exact_recovery_when_geometry_is_two_dimensional(self) -> None:
        """If the centred party matrix is exactly rank two, any spanning subset recovers the point."""
        rng = np.random.default_rng(11)
        scores = rng.normal(size=(len(PARTIES), 2))
        loadings = np.linalg.qr(rng.normal(size=(60, 2)))[0]
        matrix = scores @ loadings.T + rng.normal(size=60)
        fitted = fit_party_map(matrix, PARTIES)
        for index in range(len(PARTIES)):
            codes = matrix[index].copy()
            codes[::2] = np.nan
            point, _, reason = project_member(codes, fitted.mu, fitted.loadings, min_votes=10)
            self.assertIsNone(reason)
            np.testing.assert_allclose(point, fitted.party_scores[index], atol=1e-8)

    def test_too_few_cast_votes_unplaced(self) -> None:
        codes = np.full(self.matrix.shape[1], np.nan)
        codes[: MIN_MP_MAP_VOTES - 1] = self.matrix[0, : MIN_MP_MAP_VOTES - 1]
        point, n_cast, reason = project_member(codes, self.fitted.mu, self.fitted.loadings)
        self.assertIsNone(point)
        self.assertEqual(n_cast, MIN_MP_MAP_VOTES - 1)
        self.assertIn(str(MIN_MP_MAP_VOTES), reason)


if __name__ == "__main__":
    unittest.main()
